// Un controlador que hace de todo: atiende la peticion Y guarda los datos.
// Paso 1: sacale los datos a un servicio y pideselo por el constructor.

import { Controller, Get } from '@nestjs/common';

@Controller('usuarios')
export class UsuariosController {
  private usuarios = [
    { id: 1, nombre: 'Ana' },
    { id: 2, nombre: 'Luis' },
  ];

  @Get()
  todos() {
    return this.usuarios;
  }
}

