// Un servicio que no depende de nadie y del que dependen otros.
// Lleva la cuenta de lo que se le pide: por eso se nota si el contenedor
// crea una instancia o veinte.

import { Injectable } from '@nestjs/common';

@Injectable()
export class AuditoriaService {
  private consultas = 0;

  registrar(evento: string) {
    this.consultas = this.consultas + 1;
    console.log(JSON.stringify({ event: evento, consultas: this.consultas }));
  }
}

